class Solution {
public:
    string dayOfTheWeek(int day, int month, int year) {
        vector<string> names = {"Saturday","Sunday","Monday","Tuesday","Wednesday","Thursday","Friday"};
        int q = day, m = month, y = year;
        if (m < 3) { m += 12; y -= 1; }
        int k = y % 100, j = y / 100;
        int h = (q + 13 * (m + 1) / 5 + k + k / 4 + j / 4 + 5 * j) % 7;
        return names[h];
    }
};

